# Yêu cầu gốc: Mở trình duyệt web truy cập trang YouTube (https://www.youtube.com) hoặc mở video/tìm kiếm trên YouTube trực tiếp trên máy tính.

import urllib.parse
import webbrowser
from typing import Any, Dict, Optional

from core.plugin_manager import export_skill


@export_skill(
    name="open_youtube",
    description=(
        "Mở trang chủ YouTube, thực hiện tìm kiếm video hoặc mở một đường dẫn video YouTube cụ thể trên trình duyệt web mặc định của Windows. Cách người dùng hay yêu cầu: 'mở youtube', 'bật youtube', 'tìm kiếm youtube nhạc trẻ', 'mở bài hát trên youtube', 'phát nhạc trên YouTube'. English keywords: open youtube, search youtube, play youtube video, browse youtube. Ví dụ yêu cầu: «Mở trình duyệt web truy cập trang YouTube (https://www.youtube.com) hoặc mở video/tìm kiếm trên YouTube trực tiếp trên máy tính.»."
    ),
    parameters_schema={
        "type": "object",
        "properties": {
            "query": {
                "type": "string",
                "description": "Từ khóa tìm kiếm hoặc tên video/bài hát muốn tìm trên YouTube. Để trống nếu chỉ muốn vào trang chủ."
            },
            "url": {
                "type": "string",
                "description": "Đường dẫn YouTube cụ thể nếu có (ví dụ: https://www.youtube.com/watch?v=...)."
            }
        },
        "required": []
    }
)
def open_youtube(query: Optional[str] = None, url: Optional[str] = None) -> Dict[str, Any]:
    """
    Mở YouTube trên trình duyệt web mặc định của hệ thống Windows.

    :param query: Từ khóa tìm kiếm trên YouTube (tùy chọn).
    :param url: Đường dẫn YouTube trực tiếp (tùy chọn).
    :return: Dict chứa trạng thái kết quả thực thi.
    """
    try:
        target_url = "https://www.youtube.com"

        if url and url.strip():
            # Chỉ nhận đường dẫn http(s) có tên miền ĐÚNG là YouTube. Trước đây chỉ kiểm chuỗi con "youtube.com" nên
            # "file:///C:/x/youtube.com.exe" hay "https://evil.com/?youtube.com" lọt qua — webbrowser.open trên Windows mở được file cục bộ.
            parsed = urllib.parse.urlparse(url.strip())
            host = (parsed.hostname or "").lower()
            if parsed.scheme not in ("http", "https") or not (host in ("youtube.com", "youtu.be") or host.endswith(".youtube.com")):
                return {"status": "error", "message": "Chỉ mở được đường dẫn YouTube (https://www.youtube.com/... hoặc https://youtu.be/...)."}
            target_url = parsed.geturl()
        elif query and query.strip():
            encoded_query = urllib.parse.quote_plus(query.strip())
            target_url = f"https://www.youtube.com/results?search_query={encoded_query}"

        success = webbrowser.open(target_url, new=2)

        if success:
            return {
                "status": "success",
                "message": f"Đã mở YouTube thành công với địa chỉ: {target_url}",
                "target_url": target_url
            }
        else:
            return {
                "status": "error",
                "message": "Trình duyệt không phản hồi khi nhận yêu cầu mở URL.",
                "target_url": target_url
            }
    except Exception as exc:
        return {
            "status": "error",
            "message": f"Xảy ra lỗi khi mở YouTube: {str(exc)}"
        }
